package com.gameaggregator.tenantservice.domain; import com.gameaggregator.platform.core.common.persistence.BaseEntity; import jakarta.persistence.*; @Entity @Table(name="permissions") public class Permission extends BaseEntity { @Column(nullable=false,unique=true,length=150) private String code; @Column(length=500) private String description; protected Permission(){} public Permission(String code,String description){this.code=code;this.description=description;} public String getCode(){return code;} public String getDescription(){return description;} }
